/** 累加 order 集合的总金额 / 月度金额 / 当日金额 */
function sumOrders(orders, monthStart, todayStart) {
    let total = 0;
    let monthly = 0;
    let today = 0;
    orders.forEach((o) => {
        const amt = Number(o.totalPrice) || Number(o.price) || 0;
        total += amt;
        if (o.completedAt && new Date(o.completedAt) >= monthStart) {
            monthly += amt;
        }
        else if (o.updatedAt && new Date(o.updatedAt) >= monthStart) {
            monthly += amt;
        }
        if (o.completedAt && new Date(o.completedAt) >= todayStart) {
            today += amt;
        }
        else if (o.updatedAt && new Date(o.updatedAt) >= todayStart) {
            today += amt;
        }
    });
    return { total, monthly, today };
}
/** 累加 commission 集合的总金额 / 待结算 / 已结算 / 月度 / 当日 */
function sumCommissions(commissions, monthStart, todayStart) {
    let total = 0;
    let pending = 0;
    let settled = 0;
    let monthly = 0;
    let today = 0;
    commissions.forEach((c) => {
        const amt = Number(c.commissionAmount) || 0;
        total += amt;
        if (c.status === 'pending') {
            pending += amt;
        }
        if (c.status === 'settled') {
            settled += amt;
        }
        if (c.createdAt && new Date(c.createdAt) >= monthStart) {
            monthly += amt;
        }
        if (c.createdAt && new Date(c.createdAt) >= todayStart) {
            today += amt;
        }
    });
    return { total, pending, settled, monthly, today };
}
