async function getMyIncomeOverview(event, context, auth) {
    const { openid } = auth;
    try {
        let user = null;
        try {
            const userRes = await db.collection('users').doc(openid).get();
            user = userRes.data;
        }
        catch (e) {
            user = null;
        }
        if (!user) {
            return handleSuccess(EMPTY_OVERVIEW);
        }
        const now = new Date();
        const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
        const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const [commissionRes, hostingRes, feedingRes, walletRes] = await Promise.all([
            db.collection('tuan_commissions').where({ inviterId: openid, status: _.neq('cancelled') }).get(),
            db.collection('orders').where({ organizerId: openid, status: 'completed', type: 'boarding' }).get(),
            (async () => {
                const feederRes = await db.collection('feeders').where({ createdBy: openid }).limit(1).get();
                if (!feederRes.data || !feederRes.data.length) {
                    return { data: [] };
                }
                const feederId = feederRes.data[0]._id;
                return db.collection('feedingOrders').where({ feederId, status: 'completed' }).get();
            })(),
            db.collection('wallets').where({ openid }).limit(1).get(),
        ]);
        const commission = sumCommissions((commissionRes.data || []), monthStart, todayStart);
        const hosting = sumOrders((hostingRes.data || []), monthStart, todayStart);
        const feeding = sumOrders((feedingRes.data || []), monthStart, todayStart);
        let wallet = { ...EMPTY_WALLET };
        if (walletRes.data && walletRes.data.length > 0) {
            const w = walletRes.data[0];
            wallet = {
                balance: Number(w.balance) || 0,
                totalIncome: Number(w.totalIncome) || 0,
                totalWithdrawn: Number(w.totalWithdrawn) || 0,
                frozenAmount: Number(w.frozenAmount) || 0,
            };
        }
        return handleSuccess({ commission, hosting, feeding, wallet });
    }
    catch (error) {
        logger.error('getMyIncomeOverview', error);
        return handleError(error, '获取收入概览失败', ERROR_CODES.DATA);
    }
}
exports.getMyIncomeOverview = getMyIncomeOverview;
async function getMyIncomeDetails(event, context, auth) {
    const { openid } = auth;
    const { type = 'all', page = 1, pageSize = 20 } = event;
    try {
        let user = null;
        try {
            const userRes = await db.collection('users').doc(openid).get();
            user = userRes.data;
        }
        catch (e) {
            user = null;
        }
        if (!user) {
            return handleSuccess({ list: [], total: 0, totalAmount: 0 });
        }
        const allItems = [];
        if (type === 'all' || type === 'tuan' || type === 'mall') {
            const res = await db.collection('tuan_commissions').where({ inviterId: openid }).get();
            (res.data || []).forEach((c) => {
                const orderType = c.orderType || '';
                if (type !== 'all' && type !== orderType) return;
                const subType = orderType === 'mall' ? 'mall' : 'tuan';
                allItems.push({
                    id: c._id || '',
                    type: subType,
                    typeName: subType === 'mall' ? '商城' : '团购',
                    amount: Number(c.commissionAmount) || 0,
                    orderNo: c.orderNo || '',
                    description: `带货佣金-${orderType}`,
                    status: c.status || 'pending',
                    createdAt: c.createdAt,
                });
            });
        }
        if (type === 'all' || type === 'activity') {
            const res = await db.collection('activity_registrations').where({ userId: openid, status: 'completed' }).get();
            (res.data || []).forEach((o) => {
                allItems.push({
                    id: o._id || '',
                    type: 'activity',
                    typeName: '活动',
                    amount: Number(o.commissionAmount) || Number(o.amount) || 0,
                    orderNo: o.orderNo || '',
                    description: '活动推广收入',
                    status: 'completed',
                    createdAt: o.createdAt,
                });
            });
        }
        if (type === 'all' || type === 'hosting') {
            const res = await db.collection('orders').where({ organizerId: openid, status: 'completed', type: 'boarding' }).get();
            (res.data || []).forEach((o) => {
                allItems.push({
                    id: o._id || '',
                    type: 'hosting',
                    typeName: '寄养',
                    amount: Number(o.totalPrice) || Number(o.price) || 0,
                    orderNo: o.orderNo || '',
                    description: '寄养订单收入',
                    status: 'completed',
                    createdAt: (o.completedAt || o.updatedAt || o.createdAt),
                });
            });
        }
        if (type === 'all' || type === 'feeding') {
            const feederRes = await db.collection('feeders').where({ createdBy: openid }).limit(1).get();
            if (feederRes.data && feederRes.data.length) {
                const feederId = feederRes.data[0]._id;
                const res = await db.collection('feedingOrders').where({ feederId, status: 'completed' }).get();
                (res.data || []).forEach((o) => {
                    allItems.push({
                        id: o._id || '',
                        type: 'feeding',
                        typeName: '服务',
                        amount: Number(o.totalPrice) || 0,
                        orderNo: o.orderNo || '',
                        description: '上门服务收入',
                        status: 'completed',
                        createdAt: (o.completedAt || o.updatedAt || o.createdAt),
                    });
                });
            }
        }
        allItems.sort((a, b) => {
            const ta = a.createdAt ? new Date(a.createdAt).getTime() : 0;
            const tb = b.createdAt ? new Date(b.createdAt).getTime() : 0;
            return tb - ta;
        });
        const total = allItems.length;
        const totalAmount = allItems.reduce((sum, item) => sum + (Number(item.amount) || 0), 0);
        const start = (page - 1) * pageSize;
        const list = allItems.slice(start, start + pageSize);
        return handleSuccess({ list, total, totalAmount });
    }
    catch (error) {
        logger.error('getMyIncomeDetails', error);
        return handleError(error, '获取收入明细失败', ERROR_CODES.DATA);
    }
}
